// A cursor's held statement as a native value: when the cursor lets it go, the statement is reset
// (cached) or finalized and its in_use flag cleared, in Rust Drop, so a Cursor needs no Python __del__
// (which every discarded cursor would otherwise run through the finalizer queue).
struct StmtHold {
    st: Cell<i64>,
    cached: bool,
    stmt: V, // the Python _Statement object, to clear in_use when the hold drops
}

