def bench(fn, reps=5):
    best = 1e9
    for _ in range(reps):
        t0 = time.perf_counter()
        fn()
        dt = time.perf_counter() - t0
        if dt < best: best = dt
    return best

def fill(con):
    con.execute("drop table if exists t")
    con.execute("create table t (id integer primary key, name text, v real)")
    for i in range(n):
        con.execute("insert into t values (?, ?, ?)", (i, "n%d" % i, i * 0.25))

print("insert min", bench(lambda: fill(sqlite3.connect(":memory:"))))
con = sqlite3.connect(":memory:")
fill(con)

def point():
    s = 0.0
    for i in range(n):
        row = con.execute("select name, v from t where id = ?", (i * 7 % n,)).fetchone()
        s += row[1] + len(row[0])
    return s
print("point min", bench(point), point())

def it():
    c = 0
    for row in con.execute("select id, name, v from t"):
        c += row[0]
    return c
print("iter min", bench(it), it())
"}

